const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let db=null,filtered=[],page=1,tab='fresh',saved=new Set(),pestMap=new Map(),cropMap=new Map(),rowMap=new Map();const size=20;try{const a=JSON.parse(localStorage.getItem('china-mrl-v2-saved')||'[]');if(Array.isArray(a))saved=new Set(a.filter(x=>typeof x==='string'))}catch{}
const titles={access:['Check the other export gate.','Market access','Country, commodity and product form determine which import protocol applies.'],fresh:['Know the limit. See the source.','Fresh produce','China’s pesticide residue standard, made easier to explore for fresh produce exporters.'],full:['The entire standard, within reach.','Entire standard','Search every numeric limit in GB 2763-2026, across all food categories.'],saved:['Your reference shortlist.','Saved references','Saved on this browser, with the original food scope and crop context.'],exempt:['Know when an exemption applies.','Exempt pesticides','All 44 entries from Annex B, with links to the original text.'],sources:['Every number has a source.','Sources & coverage','Coverage, interpretation rules and the original government-hosted document.'],guide:['Understand both export gates.','Export essentials','A residue limit and permission to import are two separate requirements.']};
const key=r=>r.id+'|'+(r.cropId||'');function fromKey(k){const [id,cropId]=k.split('|'),r=rowMap.get(id);if(!r)return null;if(cropId){const c=cropMap.get(cropId);if(!c)return null;const m=MRL.matches(r,c);if(!m)return null;return {...r,cropId,match:m.match}}return r}
function toast(m){$('toast').textContent=m;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500)}
function normalized(s){return String(s).toLowerCase().replace(/[\s-]/g,'')}
function filter(){if(!db)return;const crop=cropMap.get($('crop').value),q=normalized($('search').value),pid=Number($('pesticide').value),kind=$('kind').value;let rows=tab==='saved'?[...saved].map(fromKey).filter(Boolean):tab==='full'?db.rows:crop?MRL.resolve(db.rows,crop):db.rows.filter(r=>['水果','蔬菜'].includes(r.category));filtered=rows.filter(r=>{const p=pestMap.get(r.pesticideId),c=cropMap.get(r.cropId);return (!pid||r.pesticideId===pid)&&(!(tab==='full')||!$('category').value||r.category===$('category').value)&&(!kind||(kind==='provisional'?r.provisional:r.kind===kind))&&(!q||normalized([r.food,r.foodEn,r.categoryEn,p.en,p.zh,p.residue,c?.en,c?.zh,...c?.aliases||[]].join(' ')).includes(q))});filtered.sort((a,b)=>{if(crop&&tab==='fresh')return pestMap.get(a.pesticideId).en.localeCompare(pestMap.get(b.pesticideId).en);return a.foodEn.localeCompare(b.foodEn)||pestMap.get(a.pesticideId).en.localeCompare(pestMap.get(b.pesticideId).en)});page=1;renderCrop();render()}
function renderCrop(){const c=cropMap.get($('crop').value);$('cropCard').hidden=tab!=='fresh'||!c;if(!c)return;const all=MRL.resolve(db.rows,c),direct=all.filter(r=>r.match==='direct').length;$('cropCard').innerHTML=`<div><span class="tag">SELECTED CROP · ${c.category==='水果'?'FRESH FRUIT':'FRESH VEGETABLE'}</span><h2>${esc(c.en)} <span>${esc(c.zh)}</span></h2><p>${direct} direct entries · ${all.length-direct} group-based entries</p>${typeof MarketAccess!=='undefined'&&MarketAccess.cropStatus(c.id)?`<p class="crop-access-status">Selected origin: ${{conditional:'access documented · conditions apply',restricted:'restriction documented',unverified:'market access not verified'}[MarketAccess.cropStatus(c.id).status]}. MRLs alone do not establish permission.</p>`:''}</div><div><small>PART TO BE TESTED · ANNEX A</small><p>${esc(c.part)}</p><a href="standard.pdf#page=${c.annexPage}" target="_blank" rel="noopener">Read Annex A, PDF p. ${c.annexPage} ↗</a></div>`}
function render(){page=Math.min(page,Math.max(1,Math.ceil(filtered.length/size)));$('resultCount').textContent=filtered.length.toLocaleString();$('savedCount').textContent=[...saved].filter(k=>fromKey(k)).length;$('resultLabel').textContent=tab==='full'?'source rows':tab==='saved'?'saved references':'matching limits';$('rows').innerHTML=filtered.slice((page-1)*size,page*size).map(r=>{const p=pestMap.get(r.pesticideId),c=cropMap.get(r.cropId),k=esc(key(r));return `<tr><td><strong>${esc(c?c.en:r.foodEn)}</strong><small>${esc(c?c.zh:r.food)}</small>${c?`<small class="source-scope">${r.match==='group'?'Via group: ':'Direct: '}${esc(r.food)}</small>`:`<small>${esc(r.categoryEn)}</small>`}</td><td><strong>${esc(p.en)}</strong><small>${esc(p.zh)}</small></td><td><span class="num">${r.mrl}${r.provisional?'*':''}</span><span class="unit">mg/kg</span>${r.qualifier?`<small>${esc(r.qualifier)}</small>`:''}${r.conflict?'<small class="warn">Conflicting matches · review</small>':''}${r.sourceNote?'<small class="warn">Source numbering note</small>':''}</td><td><span class="badge ${r.match==='group'?'group':''}">${r.match==='group'?'Group rule':r.kind}</span><small>Table ${r.table} · p. ${r.page}</small></td><td><div class="row-actions"><button data-save="${k}" class="${saved.has(key(r))?'saved':''}" aria-label="${saved.has(key(r))?'Unsave':'Save'} ${esc(c?c.en:r.foodEn)} ${esc(p.en)}" aria-pressed="${saved.has(key(r))}">${saved.has(key(r))?'★':'☆'}</button><button data-detail="${k}" class="view">Details ↗</button></div></td></tr>`}).join('');$('empty').hidden=filtered.length>0;$('range').textContent=filtered.length?`Showing ${(page-1)*size+1}–${Math.min(page*size,filtered.length)} of ${filtered.length.toLocaleString()}`:'0 matching numeric records';$('pageLabel').textContent=`${page} / ${Math.max(1,Math.ceil(filtered.length/size))}`;$('prev').disabled=page===1;$('next').disabled=page*size>=filtered.length;$('export').disabled=!filtered.length;$('print').disabled=!filtered.length}
function reset(){['search','pesticide','kind','category'].forEach(id=>$(id).value='');$('crop').value='';filter()}
function setTab(t){if(!titles[t])return;tab=t;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));const [title,crumb,sub]=titles[t];$('title').textContent=title;$('subtitle').textContent=sub;$('explorer').hidden=!['fresh','full','saved'].includes(t);['sources','guide','exempt','access'].forEach(id=>$(id).hidden=id!==t);$('cropLabel').hidden=t!=='fresh';$('categoryLabel').hidden=t!=='full';$('quick').hidden=t!=='fresh';$('searchTitle').textContent=t==='full'?'Search all 10,749 original entries':t==='saved'?'Your saved source references':'Find the limits for your crop';['search','pesticide','kind','category'].forEach(id=>$(id).value='');if(db){filter();if(t==='exempt')renderExempt()}}
function details(k){const r=filtered.find(x=>key(x)===k)||fromKey(k);if(!r)return;const p=pestMap.get(r.pesticideId),c=cropMap.get(r.cropId);$('detailContent').innerHTML=`<span class="tag">GB 2763-2026 · § 4.${r.table} · ${r.kind}</span><h2>${esc(c?c.en:r.foodEn)}</h2><h3>${esc(p.en)}</h3><p>${esc(r.food)} · ${esc(p.zh)}</p><div class="limit"><strong>${r.mrl}${r.provisional?'*':''}</strong> mg/kg ${esc(r.qualifier)}</div>${r.provisional?'<p class="warn">* Provisional limit (临时限量). This is not an analytical detection-limit marker.</p>':''}${r.conflict?'<p class="warn">More than one equally specific match has a different limit. Resolve applicability against the source before comparison.</p>':''}${r.sourceNote?`<p class="warn">${esc(r.sourceNote)}</p>`:''}<dl><dt>Original food scope</dt><dd>${esc(r.food)}<br>${esc(r.foodEn)}</dd><dt>Source category</dt><dd>${esc(r.categoryScope||r.category)}</dd><dt>Application</dt><dd>${c?(r.match==='group'?'Food-group match under Annex A, after explicit exclusions.':'The source table names this commodity.'): 'Original source-table row; select a fresh crop to see group applicability.'}</dd><dt>Residue definition</dt><dd lang="zh">${esc(p.residue||'Read the source section.')}</dd><dt>Effective from</dt><dd>1 March 2026</dd><dt>Source location</dt><dd>Table ${r.table} · PDF page ${r.page} · printed page ${r.page-16}</dd>${c?`<dt>Sampling portion</dt><dd>${esc(c.part)}<br><a href="standard.pdf#page=${c.annexPage}" target="_blank" rel="noopener">Annex A · PDF p. ${c.annexPage} ↗</a></dd>`:''}</dl><a href="standard.pdf#page=${r.page}" target="_blank" rel="noopener">Open the exact source page ↗</a><details><summary>Source testing-method text (Chinese)</summary><p lang="zh" class="technical">${esc(p.method||'No testing-method paragraph was extracted for this section. Consult the original standard and applicable GB 23200 methods.')}</p></details><p>Chinese source wording controls. Combined residue definitions may include metabolites or multiple active substances.</p><div class="compare-box"><h3>Compare a laboratory result</h3><label for="labMode">Report type</label><select id="labMode"><option value="number">Quantified result</option><option value="nd">Non-detect / below reporting limit</option></select><label for="lab" id="labLabel">Result in mg/kg (ppm by mass)</label><input id="lab" type="number" min="0" step="any" placeholder="e.g. 0.015"><div id="comparison" role="status">Enter a result to compare.</div><p>Arithmetic only. The analyte definition, sample preparation, uncertainty, product form and market access must be assessed separately.</p></div>`;const update=()=>{const input=$('lab'),nd=$('labMode').value==='nd';$('labLabel').textContent=nd?'Laboratory reporting limit in mg/kg':'Result in mg/kg (ppm by mass)';const v=input.value===''||!input.validity.valid?null:Number(input.value);const result=r.conflict?{status:'review',text:'Comparison blocked until the conflicting source matches are resolved.'}:MRL.compare(nd?null:v,r.mrl,nd?'nd':'number',nd?v:null);$('comparison').textContent=result.text;$('comparison').className=result.status};$('lab').addEventListener('input',update);$('labMode').addEventListener('change',()=>{$('lab').value='';update()});$('detail').showModal()}
function renderExempt(){if(!db)return;const q=normalized($('exemptSearch').value),rows=db.exemptions.filter(x=>normalized(x.en+' '+x.zh).includes(q));$('exemptRows').innerHTML=rows.length?rows.map(x=>`<div class="exempt-row"><span>${String(x.id).padStart(2,'0')}</span><div><strong>${esc(x.en)}</strong><small lang="zh">${esc(x.zh)}</small></div><a href="standard.pdf#page=${x.page}" target="_blank" rel="noopener">Annex B ↗</a></div>`).join(''):'<p>No matching Annex B entry. This does not establish an exemption.</p>'}
function downloadCsv(){const head=['Standard','Effective date','Research snapshot','Selected crop','Food scope English (navigation aid)','Food scope Chinese','Category','Original category scope','Pesticide English','Pesticide Chinese','Residue definition Chinese','Limit mg/kg','Limit type','Provisional','Qualifier','Match basis','Sampling portion','Table','PDF page','Source','Source numbering note','Applicability note'];const rows=filtered.map(r=>{const p=pestMap.get(r.pesticideId),c=cropMap.get(r.cropId);return ['GB 2763-2026','2026-03-01','2026-11-09',c?.en||'',r.foodEn,r.food,r.categoryEn,r.categoryScope||r.category,p.en,p.zh,p.residue,r.mrl,r.kind,r.provisional?'Yes':'No',r.qualifier,r.match||'Original source row',c?.part||'',r.table,r.page,db.meta.source+'#page='+r.page,r.sourceNote||'',r.conflict?'Conflicting matches; review required':'Confirm applicability, current rules and market access separately']});const quote=v=>'"'+String(v??'').replace(/^[=+@]/,"'").replace(/"/g,'""')+'"';const csv=[head,...rows].map(r=>r.map(quote).join(',')).join('\r\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='GB-2763-2026-reference.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(`Exported ${filtered.length.toLocaleString()} rows with sources`)}
$('search').addEventListener('input',filter);['crop','category','pesticide','kind'].forEach(id=>$(id).addEventListener('change',filter));$('exemptSearch').addEventListener('input',renderExempt);$('reset').onclick=reset;$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('export').onclick=downloadCsv;$('print').onclick=()=>window.print();document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)setTab(b.dataset.tab);if(b.dataset.crop){if(tab!=='fresh')setTab('fresh');['search','pesticide','kind'].forEach(id=>$(id).value='');$('crop').value=b.dataset.crop;filter()}if(b.dataset.detail)details(b.dataset.detail);if(b.dataset.save){const k=b.dataset.save;saved.has(k)?saved.delete(k):saved.add(k);try{localStorage.setItem('china-mrl-v2-saved',JSON.stringify([...saved]));toast(saved.has(k)?'Saved with source and crop context':'Reference removed')}catch{toast('Browser storage unavailable; saved for this session only')}tab==='saved'?filter():render()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('detail').open){e.preventDefault();if(!['fresh','full','saved'].includes(tab))setTab('fresh');$('search').focus()}});
fetch('database.json').then(r=>{if(!r.ok)throw Error('Data request failed');return r.json()}).then(d=>{db=d;pestMap=new Map(d.pesticides.map(p=>[p.id,p]));cropMap=new Map(d.crops.map(c=>[c.id,c]));rowMap=new Map(d.rows.map(r=>[r.id,r]));function option(id,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;$(id).append(o)}d.crops.slice().sort((a,b)=>a.en.localeCompare(b.en)).forEach(c=>option('crop',c.id,`${c.en} · ${c.zh}`));d.pesticides.slice().sort((a,b)=>a.en.localeCompare(b.en)).forEach(p=>option('pesticide',p.id,`${p.en} · ${p.zh}`));Object.entries(d.categories).forEach(([zh,en])=>option('category',zh,`${en} · ${zh}`));$('crop').value='榴莲';$('annexText').innerHTML=d.annex.map(a=>`<h4>PDF page ${a.page}</h4><pre lang="zh">${esc(a.text)}</pre>`).join('');filter();renderExempt();migrateSaved();if(typeof MarketAccess!=='undefined')MarketAccess.init(d.crops,()=>{const selected=tab==='fresh'?$('crop').value:null;setTab('access');return selected},()=>{if(tab==='fresh')renderCrop()});}).catch(e=>{$('loadError').hidden=false;$('loadError').textContent='The reference database could not load. Please reload the page; no regulatory conclusion can be drawn from this error.';$('export').disabled=true;$('print').disabled=true;console.error(e)});

async function migrateSaved(){try{if(localStorage.getItem('china-mrl-v2-migrated'))return;const old=JSON.parse(localStorage.getItem('china-mrl-saved')||'[]');if(!Array.isArray(old)||!old.length)return;const response=await fetch('data.json');if(!response.ok)return;const legacy=await response.json();for(const row of legacy.filter(r=>old.includes(r.id))){const match=db.rows.find(r=>r.table===row.table&&r.food===row.commodityZh&&r.category===({Fruit:'水果',Vegetable:'蔬菜'})[row.category]);if(match)saved.add(key(match))}localStorage.setItem('china-mrl-v2-saved',JSON.stringify([...saved]));localStorage.setItem('china-mrl-v2-migrated','1');render()}catch{/* Preserve legacy saved state if migration cannot complete. */}}
